"use strict";
// Creature specs in the build service (Cyrus R3 creature pipeline). The model writes RigSpec files
// (assets/creatures/<name>.json: archetype template or explicit bones/clips, skin palette, sound keys); this module
// checks them like code with the validator GENERATED from lib/cyrus/creature/spec.ts (./creature-spec.js) and
// cross-checks the plugin (BetterModel model key, depend, silenced invisible base mob, sound keys). The service never
// compiles models: the portal re-validates, compiles the .bbmodel + skin and records them; the server's
// Nxeon-managed BetterModel plugin builds the resource pack. Plain Node, no dependencies.
const AFX = require("./autofix");
const fs = require("fs");
const path = require("path");
const crypto = require("crypto");
const CS = require("./creature-spec");

const CREATURE_DIR = "assets/creatures";
const CREATURE_FILE_RE = /^assets\/creatures\/[a-z][a-z0-9_]{1,31}\.json$/;
/** Compile-only allowlist ids (lib/cyrus/import/deps.json) a creature build compiles against: BetterModel 3.x API for the
 * 26 family (Java 25), the 2.x API for 1.21.x (Java 21; bundle mc-coverage: BetterModel 2.2.0 flew on real Paper
 * 1.21.1/1.21.4/1.21.8/1.21.11). The server runs the Nxeon-managed BetterModel pinned for its family (lib/cyrus/managed). */
const CREATURE_DEPS = ["bettermodel-api", "bettermodel-bukkit-api"];
const CREATURE_DEPS_121 = ["bettermodel-api-2", "bettermodel-bukkit-api-2"];
const creatureDeps = (mcVersion) => (/^1\.21(\.|$)/.test(String(mcVersion || "")) ? CREATURE_DEPS_121 : CREATURE_DEPS);

function canonicalJson(v) {
  if (Array.isArray(v)) return `[${v.map(canonicalJson).join(",")}]`;
  if (v && typeof v === "object") return `{${Object.keys(v).sort().map((k) => `${JSON.stringify(k)}:${canonicalJson(v[k])}`).join(",")}}`;
  return JSON.stringify(v);
}

function listCreatureFiles(ws) {
  const dir = path.join(ws, CREATURE_DIR);
  let names = [];
  try { names = fs.readdirSync(dir, { withFileTypes: true }); } catch { return []; }
  return names.filter((e) => e.isFile()).map((e) => `${CREATURE_DIR}/${e.name}`).filter((rel) => CREATURE_FILE_RE.test(rel)).sort()
    .map((rel) => ({ rel, abs: path.join(ws, rel), size: fs.statSync(path.join(ws, rel)).size }));
}
function snapshotCreatureSpecs(ws) {
  const out = new Map();
  for (const f of listCreatureFiles(ws)) out.set(f.rel, fs.readFileSync(f.abs));
  return out;
}
function readText(files) {
  let all = "";
  for (const f of files) { try { all += fs.readFileSync(f.abs, "utf8") + "\n"; } catch { /* gone */ } }
  return all;
}

/**
 * Validate every creature spec in the workspace (same contract as checkWorkspaceTextures / checkWorkspaceSounds):
 *   problems (HARD): invalid JSON / RigSpec, file name != name, too many creatures. Dropped after the bounded
 *     repairs, never shipped.
 *   soft: the plugin should attach each model with BetterModel.model("<namespace>_<name>"), declare
 *     depend: [BetterModel], silence + hide the base mob and play the creature's sound keys. One repair, then warnings.
 */
function checkWorkspaceCreatures(ws, { namespace, javaFiles = [], pluginYml = null }) {
  const files = listCreatureFiles(ws);
  const results = [];
  const problems = [];
  const soft = [];
  let dependMissing = false;
  if (files.length > CS.MAX_CREATURES) problems.push(`${files.length} creature spec files; the limit is ${CS.MAX_CREATURES}. Drop some.`);
  for (const f of files.slice(0, CS.MAX_CREATURES)) {
    const want = path.basename(f.rel, ".json");
    const r = { rel: f.rel, name: want, ok: false, problems: [] };
    results.push(r);
    if (f.size > CS.MAX_RIG_SPEC_BYTES) { r.problems.push(`${f.rel} is larger than ${CS.MAX_RIG_SPEC_BYTES / 1024} KB`); continue; }
    let json;
    try { json = JSON.parse(fs.readFileSync(f.abs, "utf8")); } catch (e) { r.problems.push(`${f.rel} is not valid JSON: ${String(e.message).slice(0, 160)}`); continue; }
    const c = CS.checkRigSpec(json, { namespace });
    if (!c.ok) { r.problems.push(`${f.rel}: ${c.error}`); continue; }
    if (c.spec.name !== want) { r.problems.push(`${f.rel}: "name" is "${c.spec.name}" but the file is ${want}.json; they must match`); continue; }
    r.spec = json; r.expanded = c.spec; r.stats = c.stats; r.warnings = c.warnings;
    r.sha256 = crypto.createHash("sha256").update(canonicalJson(json)).digest("hex");
  }
  if (files.length && javaFiles.length) {
    const text = readText(javaFiles);
    if (!/\bBetterModel\s*\.\s*model(OrNull)?\s*\(/.test(text)) soft.push(`The plugin never attaches a model: call BetterModel.model("${namespace}_<name>").map(r -> r.create(BukkitAdapter.adapt(baseMob))) for each creature.`);
    for (const r of results) {
      if (!r.expanded) continue;
      const key = CS.modelKey(namespace, r.name);
      if (!text.includes(`"${key}"`)) soft.push(`${r.rel}: the plugin never uses the model key "${key}" (BetterModel.model("${key}"))`);
      for (const [role, sk] of Object.entries(r.expanded.sounds || {})) if (!text.includes(`"${sk}"`)) soft.push(`${r.rel}: the creature's ${role} sound "${sk}" is never played; play it with world.playSound(location, "${sk}", SoundCategory.HOSTILE, 1.0f, 1.0f)`);
    }
    if (!/setSilent\s*\(\s*true\s*\)/.test(text)) soft.push("The base mob must be silent: call setSilent(true) on it (the creature plays its own sounds).");
    if (!/setInvisible\s*\(\s*true\s*\)/.test(text)) soft.push("The base mob must be invisible: call setInvisible(true) on it (BetterModel draws the creature).");
    if (pluginYml != null && !AFX.declaredPlugins(pluginYml).depend.some((x) => x.toLowerCase() === "bettermodel")) {
      dependMissing = true;
      soft.push("plugin.yml must declare depend: [BetterModel] (the Nxeon-managed engine that draws the creatures).");
    }
  }
  for (const r of results) { r.ok = r.problems.length === 0; problems.push(...r.problems); }
  return { files, results, dependMissing, problems: [...new Set(problems)], soft: [...new Set(soft)].slice(0, 30) };
}

module.exports = { CREATURE_DIR, CREATURE_FILE_RE, CREATURE_DEPS, CREATURE_DEPS_121, creatureDeps, CS, canonicalJson, listCreatureFiles, snapshotCreatureSpecs, checkWorkspaceCreatures };
"use strict";
// Designs in the build service (Cyrus R3 gameplay designers). The model writes design files at assets/designs/<id>.json:
// ItemDesign (a custom item + its typed ability graph; no "kind" or kind "item"), MenuDesign (kind "menu": a GUI menu,
// shop list or dialogue) and QuestDesign (kind "quest"); this module checks them like code with the
// validator GENERATED from lib/cyrus/designer (./designer-spec.js) for the build's exact version, and COMPILES them into
// the workspace sources (the verified component library + straight generated Java + plugin.yml + config.yml) before the
// normal validate / precheck / javac / scan. Free-form Java is allowed only in <package>.custom (CustomHooks), for what
// the graph cannot express. The portal re-validates and re-compiles (the service is not trusted). Plain Node.
const fs = require("fs");
const path = require("path");
const DZ = require("./designer-spec");
const IMS = require("./itemmodels");

const DESIGN_DIR = "assets/designs";
const DESIGN_FILE_RE = /^assets\/designs\/[a-z][a-z0-9_]{1,31}\.json$/;
const MAX_DESIGN_FILES = DZ.GAMEPLAY_LIMITS.maxDesignFiles; // items + menus + quests (per-kind caps below)
const KIND_CAPS = { item: DZ.DESIGN_LIMITS.maxItems, menu: DZ.GAMEPLAY_LIMITS.maxMenus, quest: DZ.GAMEPLAY_LIMITS.maxQuests, boss: DZ.BOSS_LIMITS.maxBosses, encounter: DZ.BOSS_LIMITS.maxEncounters, hud: DZ.HUD_LIMITS.maxHuds, motion: DZ.MOTION_DESIGN_LIMITS.maxMotions };

function listDesignFiles(ws) {
  const dir = path.join(ws, DESIGN_DIR);
  let names = [];
  try { names = fs.readdirSync(dir, { withFileTypes: true }); } catch { return []; }
  return names.filter((e) => e.isFile()).map((e) => `${DESIGN_DIR}/${e.name}`).filter((rel) => DESIGN_FILE_RE.test(rel)).sort()
    .map((rel) => ({ rel, abs: path.join(ws, rel), size: fs.statSync(path.join(ws, rel)).size }));
}
function snapshotDesignSpecs(ws) {
  const out = new Map();
  for (const f of listDesignFiles(ws)) out.set(f.rel, fs.readFileSync(f.abs));
  return out;
}
function designVersionOk(mcVersion) { return DZ.designFeatures(String(mcVersion)).ok; }

/**
 * Item model keys of this mod's texture specs (assets/textures/<name>.json -> <ns>:<name>), its sound keys and its data
 * pack advancements (R3 quest rewards); with a version, also the item model states of assets/itemmodels (model key ->
 * modes / flags / use), only when there are any.
 */
function assetKeysOf(ws, namespace, mcVersion) {
  const models = [], sounds = [], advancements = [], lootTables = [];
  const read = (dir) => { try { return fs.readdirSync(path.join(ws, dir)).filter((n) => /^[a-z][a-z0-9_]{1,31}\.json$/.test(n)).sort(); } catch { return []; } };
  for (const n of read("assets/textures")) models.push(`${namespace}:${n.slice(0, -5)}`);
  for (const n of read("assets/sounds")) {
    try { const s = JSON.parse(fs.readFileSync(path.join(ws, "assets/sounds", n), "utf8")); for (const e of (s && Array.isArray(s.events) ? s.events : [])) if (e && typeof e.event === "string") sounds.push(`${namespace}:${n.slice(0, -5)}.${e.event}`); } catch { /* unreadable spec: no keys */ }
  }
  // R3 quest rewards: advancements of this project's data pack specs (assets/datapack/<name>.json resources)
  for (const n of read("assets/datapack")) {
    try { const s = JSON.parse(fs.readFileSync(path.join(ws, "assets/datapack", n), "utf8")); for (const r of (s && Array.isArray(s.resources) ? s.resources : [])) { if (r && r.type === "advancement" && typeof r.id === "string") advancements.push(`${namespace}:${r.id}`); if (r && r.type === "loot_table" && typeof r.id === "string") lootTables.push(`${namespace}:${r.id}`); } } catch { /* unreadable spec: no keys */ }
  }
  const itemModels = mcVersion ? IMS.itemModelNeedsOf(ws, namespace, mcVersion) : {};
  return { models, sounds, advancements, lootTables, ...(Object.keys(itemModels).length ? { itemModels } : {}) };
}

/**
 * Validate every design in the workspace (same contract as checkWorkspaceDatapacks):
 *   problems (HARD): invalid JSON / design, file name != id, cross-file duplicates, more files than allowed. Dropped after
 *   the bounded repairs, never shipped. soft: warnings worth one repair round (unresolved asset keys are only warnings).
 */
function checkWorkspaceDesigns(ws, { namespace, mcVersion }) {
  const files = listDesignFiles(ws);
  const results = [];
  const problems = [];
  if (files.length > MAX_DESIGN_FILES) problems.push(`${files.length} design files; the limit is ${MAX_DESIGN_FILES}. Put fewer items in this mod.`);
  const parsed = [];
  for (const f of files.slice(0, MAX_DESIGN_FILES)) {
    const want = path.basename(f.rel, ".json");
    const r = { rel: f.rel, name: want, ok: false, problems: [], warnings: [] };
    results.push(r);
    if (f.size > DZ.DESIGN_LIMITS.maxSpecBytes) { r.problems.push(`${f.rel} is larger than ${DZ.DESIGN_LIMITS.maxSpecBytes / 1024} KB`); continue; }
    try { r.json = JSON.parse(fs.readFileSync(f.abs, "utf8")); } catch (e) { r.problems.push(`${f.rel} is not valid JSON: ${String(e.message).slice(0, 160)}`); continue; }
    if (!r.json || r.json.id !== want) { r.problems.push(`${f.rel}: "id" is "${r.json && r.json.id}" but the file is ${want}.json; they must match`); continue; }
    parsed.push(r);
  }
  const assets = assetKeysOf(ws, namespace, mcVersion);
  // one mod-level validation of every kind (items: the unchanged item validator; menus/quests: the cross-file checks)
  const v = DZ.validateGameplay(parsed.map((r) => r.json), { version: String(mcVersion), namespace, assets });
  const seen = { item: 0, menu: 0, quest: 0, boss: 0, encounter: 0, hud: 0, motion: 0 };
  const specs = new Map([...v.items, ...v.menus, ...v.quests, ...(v.bosses || []), ...(v.encounters || []), ...(v.huds || []), ...(v.motions || []).map((m) => m.design)].map((d) => [d.id, d]));
  let itemIndex = 0;
  parsed.forEach((r, i) => {
    const f = v.files[i];
    r.kind = f.kind || "item";
    if (f.kind && seen[f.kind] !== undefined && ++seen[f.kind] > KIND_CAPS[f.kind]) r.problems.push(`${r.rel}: more than ${KIND_CAPS[f.kind]} ${f.kind} designs in one mod; this one is left out`);
    for (const e of f.errors.slice(0, 12)) r.problems.push(`${r.rel}: ${e.path}: ${e.message}`);
    r.warnings = f.warnings.map((w) => `${w.path}: ${w.message}`).slice(0, 10);
    if (r.kind === "item") { const ir = v.itemResults[itemIndex++]; if (ir) r.budgets = ir.budgets; }
    const spec = specs.get(r.json.id);
    if (!r.problems.length && spec) {
      r.spec = spec;
      r.sha256 = require("crypto").createHash("sha256").update(DZ.canonicalJson(spec)).digest("hex");
    }
  });
  // mod-level errors no file can be blamed for (counts are handled per file above)
  for (const e of v.errors) if (!e.file && !["too_many_items", "too_many_menus", "too_many_quests", "too_many_bosses", "too_many_encounters", "too_many_huds", "too_many_motions", "too_many_files"].includes(e.code)) problems.push(`${e.path}: ${e.message}`);
  for (const r of results) { r.ok = r.problems.length === 0 && !!r.spec; problems.push(...r.problems); }
  return { files, results, problems: [...new Set(problems)], soft: [], assets, progressChars: v.progressChars };
}

function pkgOf(pluginName) {
  const lower = String(pluginName).toLowerCase().replace(/_/g, "");
  return `dev.nxeon.plugins.${/^[a-z]/.test(lower) ? lower : `p${lower}`}`;
}

/** The plugin name for a designer build: the request's, else modbuilder.json's, else the first item's id. */
function pluginNameFor(ws, rec, specs) {
  const ok = (s) => typeof s === "string" && /^[A-Za-z][A-Za-z0-9_]{1,39}$/.test(s);
  if (ok(rec.pluginName)) return rec.pluginName;
  try { const s = JSON.parse(fs.readFileSync(path.join(ws, "modbuilder.json"), "utf8")); if (ok(s && s.name)) return s.name; } catch { /* none */ }
  const first = specs.find((d) => !d.kind || d.kind === "item") || specs[0];
  const id = first ? first.id : "designer_items";
  return id.split("_").filter(Boolean).map((p) => p[0].toUpperCase() + p.slice(1)).join("").slice(0, 40) || "DesignerItems";
}

function walk(dir, out = []) {
  let ents = [];
  try { ents = fs.readdirSync(dir, { withFileTypes: true }); } catch { return out; }
  for (const e of ents) { const p = path.join(dir, e.name); if (e.isDirectory()) walk(p, out); else out.push(p); }
  return out;
}

/**
 * Compile the valid designs into the workspace: every Java file outside <package>/custom/ and the plugin.yml /
 * paper-plugin.yml / config.yml are REPLACED by the generated ones (the model never edits generated code; its free-form
 * Java lives in custom/). config_version follows the previous config.yml (kept when the designer values are unchanged).
 */
function compileWorkspaceDesigns(ws, rec, specs) {
  const pluginName = pluginNameFor(ws, rec, specs);
  const pkg = pkgOf(pluginName);
  const javaRoot = path.join(ws, "src/main/java");
  const customDir = path.join(javaRoot, pkg.replace(/\./g, "/"), "custom");
  const customHooks = fs.existsSync(path.join(customDir, "CustomHooks.java"));
  const cfgPath = path.join(ws, "src/main/resources/config.yml");
  let previousConfig;
  try { const t = fs.readFileSync(cfgPath, "utf8"); if (/^# designer-values: [0-9a-f]{16}$/m.test(t)) previousConfig = t; } catch { /* first build */ }
  const assets = assetKeysOf(ws, rec.assets.namespace, rec.mcVersion);
  const r = DZ.compileMod(specs, { version: String(rec.mcVersion), namespace: rec.assets.namespace, pluginName, customHooks, previousConfig, assets: { models: assets.models, sounds: assets.sounds, advancements: assets.advancements, lootTables: assets.lootTables, ...(assets.itemModels ? { itemModels: assets.itemModels } : {}) } });
  if (!r.ok) return { ok: false, errors: r.errors.map((e) => `${e.path}: ${e.message}`).slice(0, 12) };
  let replaced = 0;
  for (const abs of walk(javaRoot)) {
    if (abs.startsWith(customDir + path.sep)) continue;
    fs.rmSync(abs, { force: true }); replaced++;
  }
  for (const n of ["plugin.yml", "paper-plugin.yml", "config.yml"]) fs.rmSync(path.join(ws, "src/main/resources", n), { force: true });
  for (const f of r.files) { const abs = path.join(ws, f.path); fs.mkdirSync(path.dirname(abs), { recursive: true }); fs.writeFileSync(abs, f.content); }
  return {
    ok: true, replaced,
    summary: {
      hash: r.hash, pluginName, pkg: r.pkg, mainClass: r.mainClass, command: r.command, configVersion: r.configVersion, designerValuesHash: r.designerValuesHash,
      customHooks, modelsApplied: r.modelsApplied, ...(assets.itemModels ? { itemModels: assets.itemModels } : {}), compiler: r.compiler, library: r.library, libraryHash: r.libraryHash, javacVerified: r.javacVerified,
      files: r.files.map((f) => ({ path: f.path, sha256: f.sha256, role: f.role })), readme: r.readme, notes: r.notes,
      params: r.params.map((p) => ({ path: p.path, kind: p.kind, min: p.min, max: p.max, value: p.value, label: p.label })),
      warnings: r.warnings.map((w) => `${w.path}: ${w.message}`).slice(0, 20),
      counts: r.counts, deps: r.deps, gameplay: r.gameplay, ...(r.motionCompile ? { motionCompile: r.motionCompile } : {}),
    },
  };
}

// Cyrus r31: a DESIGNER EDIT build request. The Designer Studio saved a revision of the mod's designs; the portal sends
// the full set (same ids as the base build, never added / removed / renamed) and the service compiles them with NO model
// call. Shape only here; the design checks run in the workspace (checkWorkspaceDesigns), exactly as for a model build.
const DESIGN_ID_RE = /^[a-z][a-z0-9_]{1,31}$/;
const MAX_DESIGN_EDIT_BYTES = 512 * 1024;
function parseDesignEdit(raw, baseRec) {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return { error: "designEdit must be an object" };
  if (!baseRec) return { error: "designEdit needs baseBuildId" };
  if (!baseRec.assets || !baseRec.assets.design) return { error: "designEdit needs a base build with designs" };
  if (baseRec.imported) return { error: "designEdit is not available for imported plugins" };
  if (baseRec.assets.creature) return { error: "designEdit is not available for mods with animated creatures yet" };
  const files = raw.files;
  if (!Array.isArray(files) || !files.length || files.length > MAX_DESIGN_FILES) return { error: `designEdit.files must hold 1-${MAX_DESIGN_FILES} designs` };
  const out = [], seen = new Set();
  for (const f of files) {
    const spec = f && typeof f === "object" ? f.spec : null;
    const id = f && typeof f.id === "string" ? f.id : "";
    if (!DESIGN_ID_RE.test(id) || seen.has(id)) return { error: "designEdit.files: every design needs a unique id" };
    if (!spec || typeof spec !== "object" || Array.isArray(spec) || spec.id !== id) return { error: `designEdit.files: ${id} needs its spec (spec.id = id)` };
    seen.add(id); out.push({ id, spec });
  }
  if (Buffer.byteLength(JSON.stringify(out)) > MAX_DESIGN_EDIT_BYTES) return { error: "designEdit is too large" };
  const revisionId = typeof raw.revisionId === "string" && /^[A-Za-z0-9_-]{1,64}$/.test(raw.revisionId) ? raw.revisionId : null;
  return { files: out.sort((a, b) => (a.id < b.id ? -1 : 1)), revisionId };
}

module.exports = { DESIGN_DIR, DESIGN_FILE_RE, MAX_DESIGN_FILES, KIND_CAPS, DZ, listDesignFiles, snapshotDesignSpecs, designVersionOk, assetKeysOf, checkWorkspaceDesigns, compileWorkspaceDesigns, pluginNameFor, pkgOf, parseDesignEdit };
"use strict";
// rc13 (owner QA batch 2026-10-14, boss-minions + food-potions): a lane the PLAN promised that shipped nothing must never be
// silent. boss-minions planned a creature lane, spent 5 attempts and $1.24, and the build said "succeeded" with no creature;
// food-potions planned a data pack and shipped none. This pure module compares the plan with what shipped and returns one
// honest entry per missing lane (plus an owner/customer sentence). Lanes that were already reported as downgraded (left out
// after failing a check) are not repeated: they have their own wording. Plain Node, no I/O.

const LABEL = {
  texture: "custom texture", itemStates: "item model states", sound: "custom sound", model3d: "3D model", creature: "animated creature",
  designItem: "item design", designMenu: "menu design", designQuest: "quest design", designBoss: "boss design", designHud: "HUD design", motion: "animated prop",
  datapack: "data pack", worldgen: "world generation data pack",
};
/** planner lane -> the shipped-asset group that satisfies it ("designs" = any compiled design). null = not checkable here. */
const SHIPPED_BY = {
  texture: "textures", sound: "sounds", creature: "creatures", datapack: "datapacks", worldgen: "datapacks", itemStates: "itemModels",
  designItem: "designs", designMenu: "designs", designQuest: "designs", designBoss: "designs", designHud: "designs", motion: "designs",
};
const KIND_BY = { texture: "texture", sound: "sound", creature: "creature", datapack: "datapack", worldgen: "datapack", itemStates: "itemmodel", designItem: "design", designMenu: "design", designQuest: "design", designBoss: "design", designHud: "design", motion: "design" };
/** assets flag that switches each lane on in the service (a lane whose flag is off was turned off by a gate or a conflict). */
const FLAG_BY = { texture: "texture", sound: "sound", creature: "creature", datapack: "datapack", worldgen: "worldgen", itemStates: "itemmodel", designItem: "design", designMenu: "design", designQuest: "design", designBoss: "design", designHud: "design", motion: "design" };

/**
 * assets = rec.assets (plan, flags, laneOff); shipped = { textures, sounds, creatures, datapacks, itemModels, designs } counts;
 * downgraded = rec.assetDowngrades kinds already reported. Returns [{ lane, label, what, state: "off"|"empty", why, sentence }].
 */
function laneGaps(assets, shipped, downgraded) {
  const plan = assets && Array.isArray(assets.plan) ? assets.plan : [];
  const out = [];
  const seen = new Set();
  const down = new Set((downgraded || []).map((d) => d && d.kind).filter(Boolean));
  for (const p of plan) {
    const lane = p && p.lane;
    const group = SHIPPED_BY[lane];
    if (!group || seen.has(group)) continue;
    if ((shipped[group] || 0) > 0) { seen.add(group); continue; }
    if (down.has(KIND_BY[lane])) continue; // reported as "left out" already
    seen.add(group);
    const label = LABEL[lane] || lane;
    const off = !assets[FLAG_BY[lane]];
    const why = off
      ? ((assets.laneOff && assets.laneOff[lane]) || "that lane was switched off for this build")
      : `the build wrote no ${label} spec (the plugin may implement it in code instead)`;
    out.push({
      lane, label, what: String(p.what || "").slice(0, 200), state: off ? "off" : "empty", why,
      sentence: `The planned ${label} part was not delivered: ${why}. The build itself still works; ask for it in a change request or Refine to try again.`.slice(0, 300),
    });
  }
  return out.slice(0, 8);
}

module.exports = { laneGaps, LABEL };
// Generated files of the Cyrus gameplay designers (committed, so the build service needs no esbuild or zod at runtime;
// test/cyrus-designer.test.ts rebuilds them in memory and fails when one is stale):
//   services/modbuilder/designer-spec.js          the build service's validator + compiler, bundled from lib/cyrus/designer
//   lib/cyrus/designer/designer.v1.schema.json    the portable ItemDesign contract (JSON Schema)
//   lib/cyrus/designer/gameplay.v1.schema.json    the portable MenuDesign / QuestDesign contract (JSON Schema)
//   lib/cyrus/designer/boss.v1.schema.json        the portable BossDesign / EncounterDesign contract (JSON Schema)
//   lib/cyrus/designer/hud.v1.schema.json         the portable HudDesign contract (JSON Schema)
//   lib/cyrus/designer/motion/motion-design.v1.schema.json  the portable MotionDesign contract (JSON Schema)
//   npx tsx scripts/cyrus/build-designer-artifacts.ts [--check] [--out-dir DIR]   (DIR: write there instead of the repo, e.g. on a build host)
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { designJsonSchema } from "../../lib/cyrus/designer/spec";
import { gameplayJsonSchema } from "../../lib/cyrus/designer/gameplay/spec";
import { bossJsonSchema } from "../../lib/cyrus/designer/boss/spec";
import { hudJsonSchema } from "../../lib/cyrus/designer/hud/spec";
import { motionDesignJsonSchema } from "../../lib/cyrus/designer/motion/spec";

const ROOT = path.join(__dirname, "../..");

export async function designerArtifacts(): Promise<Record<string, string>> {
  const esbuild = await import("esbuild");
  const r = await esbuild.build({
    entryPoints: [path.join(ROOT, "lib/cyrus/designer/service-entry.ts")], bundle: true, platform: "node", format: "cjs", target: "node20", write: false,
    minify: true, keepNames: true, legalComments: "none", banner: { js: `"use strict";\n// GENERATED by scripts/cyrus/build-designer-artifacts.ts from lib/cyrus/designer/*.ts (+ zod, the version registry and the data pack id lists). Do not edit.` },
  });
  return {
    "services/modbuilder/designer-spec.js": r.outputFiles[0].text,
    "lib/cyrus/designer/designer.v1.schema.json": JSON.stringify(designJsonSchema(), null, 1) + "\n",
    "lib/cyrus/designer/gameplay.v1.schema.json": JSON.stringify(gameplayJsonSchema(), null, 1) + "\n",
    "lib/cyrus/designer/boss.v1.schema.json": JSON.stringify(bossJsonSchema(), null, 1) + "\n",
    "lib/cyrus/designer/hud.v1.schema.json": JSON.stringify(hudJsonSchema(), null, 1) + "\n",
    "lib/cyrus/designer/motion/motion-design.v1.schema.json": JSON.stringify(motionDesignJsonSchema(), null, 1) + "\n",
  };
}

if (require.main === module) {
  designerArtifacts().then((files) => {
    let stale = 0;
    const oi = process.argv.indexOf("--out-dir");
    for (const [rel, text] of Object.entries(files)) {
      const abs = oi > 0 ? path.join(process.argv[oi + 1], path.basename(rel)) : path.join(ROOT, rel);
      if (process.argv.includes("--check")) {
        let cur = ""; try { cur = readFileSync(abs, "utf8"); } catch { /* missing */ }
        if (cur !== text) { stale++; console.error(`stale: ${rel}`); }
      } else { writeFileSync(abs, text); console.log(`wrote ${rel} (${Buffer.byteLength(text)} bytes)`); }
    }
    if (stale) { console.error("run: npx tsx scripts/cyrus/build-designer-artifacts.ts"); process.exit(1); }
  }).catch((e) => { console.error(e); process.exit(1); });
}

