158	// ---------------------------------------------------------------------------------------------------- Java codegen
159	type Gen = { params: Map<string, BossParam>; ns: string; out: string[] };
160	const F = (g: Gen, rel: string) => { const p = g.params.get(rel); if (!p) throw new Error(`internal: no parameter ${rel}`); return p.field; };
161	const has = (g: Gen, rel: string) => g.params.has(rel);
162	const ind = (n: number) => "    ".repeat(n);
163	const DEFAULT_TEXT_COLOR = "NamedTextColor.YELLOW";
164	
165	function emitActions(g: Gen, list: BossAction[], rel: string, depth: number, prefix = "a"): void {
166	  const o = g.out, I = ind(depth);
167	  list.forEach((a, k) => {
168	    const r = `${rel}.${prefix}${k}`;
169	    const p = (f: string) => F(g, `${r}.${f}`);
170	    o.push(`${I}// ${r.split(".").slice(-1)[0]}: ${a.type}`);
171	    const per = isPerTarget(a);
172	    const color = "color" in a && a.color ? colorExpr(a.color) : DEFAULT_TEXT_COLOR;
173	    let call: string;
174	    switch (a.type) {
175	      case "damage": call = `fx.damage(c.at(t), t, ${p("amount")});`; break;
176	      case "knockback": call = `fx.knockback(c.at(t), t, ${p("strength")}, ${p("vertical")});`; break;
177	      case "pull": call = `fx.pull(c.at(t), t, ${p("strength")}, ${p("vertical")});`; break;
178	      case "potion_effect": call = `fx.potion(c.at(t), t, PotionEffectType.${a.effect.toUpperCase()}, (int) ${p("duration_ticks")}, ${p("amplifier")});`; break;
179	      case "launch_projectile": call = `fx.launch(c.at(t), t, ${jstr(a.kind)}, ${p("speed")}, ${p("damage")});`; break;
180	      case "spawn_particles": call = `fx.particles(c, ${per ? "fx.at(t)" : "fx.at(c)"}, Particle.${a.particle.toUpperCase()}, ${p("count")}, ${p("spread")}, ${p("speed")});`; break;
181	      case "play_sound": call = `fx.sound(c, ${per ? "fx.at(t)" : "fx.at(c)"}, ${p("sound")}, (float) ${p("volume")}, (float) ${p("pitch")});`; break;
182	      case "send_message": call = per ? `fx.message(c, t, ${p("text")}, ${color});` : `fx.arenaMessage(c, ${p("text")}, ${color});`; break;
183	      case "actionbar": call = per ? `fx.actionbar(c, t, ${p("text")}, ${color});` : `fx.arenaActionbar(c, ${p("text")}, ${color});`; break;
184	      case "title": { const sub = has(g, `${r}.subtitle`) ? p("subtitle") : "null"; call = per ? `fx.title(c, t, ${p("title")}, ${sub}, ${color});` : `fx.arenaTitle(c, ${p("title")}, ${sub}, ${color});`; break; }
185	      case "leap": call = `fx.leap(c, ${p("strength")}, ${p("vertical")});`; break;
186	      case "summon": { const cls = ENTITY_CLASS[bare(a.entity)]; const w = DEFAULT_WEAPON[bare(a.entity)]; call = `fx.summon(c, ${cls}.class, ${w ? MATERIAL(w) : "null"}, ${p("count")}, ${has(g, `${r}.health`) ? p("health") : "-1.0"});`; break; }
187	      case "heal_self": call = `fx.healSelf(c, ${p("amount")});`; break;
188	      case "self_effect": call = `fx.selfEffect(c, PotionEffectType.${a.effect.toUpperCase()}, (int) ${p("duration_ticks")}, ${p("amplifier")});`; break;
189	      case "delayed":
190	        o.push(`${I}if (!c.budget().action()) return;`);
191	        o.push(`${I}c.later(${p("delay_ticks")}, () -> {`);
192	        emitActions(g, a.actions, r, depth + 1, "n");
193	        o.push(`${I}});`);
194	        return;
195	    }
196	    if (per) o.push(`${I}for (LivingEntity t : c.targets()) { if (!c.budget().action()) return; ${call} }`);
197	    else o.push(`${I}if (!c.budget().action()) return;`, `${I}${call}`);
