432	export function bossReadme(bosses: BossDesign[], encounters: EncounterDesign[], command: string, ns: string): string[] {
433	  const out: string[] = [];
434	  if (bosses.length) out.push(`## Bosses`, ``);
435	  for (const b of bosses) {
436	    const how = [b.spawn?.command !== false ? `\`/${command} boss spawn ${b.id}\` (operators)` : "", b.spawn?.item ? `right-click with ${b.spawn.item.replace(/_/g, " ")} (used up)` : "", encounters.some((e) => e.waves.some((w) => w.spawns.some((s) => s.boss === b.id))) ? "in an encounter" : ""].filter(Boolean).join(", ");
437	    out.push(`- **${b.name.text}** (${bare(b.entity).replace(/_/g, " ")}, ${b.stats.health} health): ${how}. Arena ${b.arena.radius} blocks; despawns after ${secs(b.arena.emptyDespawnSeconds)} without players${b.arena.maxDurationSeconds ? `; after ${secs(b.arena.maxDurationSeconds)} it ${b.arena.onTimeout === "enrage" ? "enrages" : "leaves"}` : ""}.`);
438	    b.phases.forEach((ph, i) => out.push(`  ${i + 1}. ${ph.name ?? ph.id}${i ? ` (below ${Math.round(ph.below * 100)}% health)` : ""}: ${ph.attacks.map((x) => b.attacks.find((a) => a.id === x.attack)?.name ?? x.attack).join(", ")} every ${secs(+(ph.intervalTicks / 20).toFixed(2))}`));
439	    const d = b.drops;
440	    if (d) out.push(`  - Drops ${d.mode === "participants" ? `to every player who did at least ${Math.round((d.minDamageShare ?? BOSS_DEFAULTS.minDamageShare) * 100)}% of the damage` : "on the ground"}: ${[...(d.items ?? []).map((x) => `${x.count} x ${bare(x.item).replace(/_/g, " ")} (${Math.round(x.chance * 1000) / 10}%)`), ...(d.lootTable ? [`loot table ${d.lootTable}`] : []), ...(d.xp ? [`${d.xp} XP`] : [])].join(", ") || "nothing"}.`);
441	  }
442	  if (bosses.length) out.push(``);
443	  if (encounters.length) out.push(`## Encounters`, ``);
444	  for (const e of encounters) {
445	    out.push(`- **${e.title}**: ${[e.start?.command !== false ? `\`/${command} encounter start ${e.id}\` (operators)` : "", e.start?.item ? `right-click with ${e.start.item.replace(/_/g, " ")}` : ""].filter(Boolean).join(", ")}. ${e.waves.length} wave${e.waves.length === 1 ? "" : "s"}, at most ${e.maxAlive} mobs at once.`);
446	    e.waves.forEach((w, i) => out.push(`  ${i + 1}. ${w.spawns.map((s) => (s.boss ? `boss ${s.boss}` : `${s.count} x ${bare(s.entity!).replace(/_/g, " ")}`)).join(", ")} (${w.advance === "cleared" ? "clear it" : `next wave after ${w.seconds} s`})`));
447	  }
448	  if (encounters.length) out.push(``);
449	  void ns;
450	  return out;
451	}
