706	    List<Player> playersNear(Location home, double radius) {
707	        List<Player> out = new ArrayList<>();
708	        World w = home.getWorld();
709	        if (w == null) return out;
710	        double r2 = radius * radius;
711	        for (Player p : w.getPlayers()) {
712	            if (!p.isOnline() || p.isDead() || !p.isValid()) continue;
713	            if (p.getGameMode() != GameMode.SURVIVAL && p.getGameMode() != GameMode.ADVENTURE) continue;
714	            if (p.getLocation().distanceSquared(home) <= r2) out.add(p);
715	        }
716	        out.sort(Comparator.comparing(Player::getUniqueId));
717	        return out;
718	    }
