720	    /** Targets of an attack: participants within range of the boss, ordered by the attack's mode, at most max. */
721	    List<LivingEntity> targets(BossInstance i, BossDef.Attack a, List<Player> ps) {
722	        List<LivingEntity> out = new ArrayList<>();
723	        if (a.select == BossDef.Select.SELF) return out;
724	        Location at = i.mob.getLocation();
725	        double r2 = a.range * a.range;
726	        for (Player p : ps) if (p.getWorld().equals(at.getWorld()) && p.getLocation().distanceSquared(at) <= r2) out.add(p);
727	        order(out, at, a.select);
728	        return out.size() > a.max ? new ArrayList<>(out.subList(0, a.max)) : out;
729	    }
730	
731	    void order(List<LivingEntity> out, Location at, BossDef.Select select) {
732	        out.sort(Comparator.comparingDouble((LivingEntity e) -> e.getLocation().distanceSquared(at)).thenComparing(Entity::getUniqueId));
733	        if (select == BossDef.Select.FARTHEST) Collections.reverse(out);
734	        else if (select == BossDef.Select.RANDOM) Collections.shuffle(out, random);
735	    }
