737	    Location spotNear(Location c, double r, int k, int n) {
738	        double ang = (Math.PI * 2.0 * k) / Math.max(1, n);
739	        Location p = c.clone().add(Math.cos(ang) * r, 0, Math.sin(ang) * r);
740	        Location safe = Effects.safeAt(p);
741	        if (safe != null) return safe;
742	        return Effects.safeAt(c.clone());
743	    }
