745	    // ---------------------------------------------------------------------------------------------- spawning
746	    /** Spawn a boss; returns null on success (the instance is live) or the reason it did not spawn. */
747	    public String spawn(BossDef def, Location at, String encounter) {
748	        if (at == null || at.getWorld() == null) return "no location";
749	        World w = at.getWorld();
750	        if (w.getDifficulty() == Difficulty.PEACEFUL) return "the world is on peaceful difficulty (the game removes hostile mobs)";
751	        if (!w.isChunkLoaded(at.getBlockX() >> 4, at.getBlockZ() >> 4)) return "that spot is not loaded";
752	        if (live.size() >= MAX_LIVE) return "already " + MAX_LIVE + " bosses alive (the limit)";
753	        int same = 0;
754	        for (BossInstance i : live) if (i.def == def) same++;
755	        if (same >= def.maxAlive) return def.id() + " is already alive (" + same + "/" + def.maxAlive + ")";
756	        long now = d.now();
757	        Long last = lastSpawn.get(def.id());
758	        if (encounter == null && last != null && def.spawnCooldownTicks > 0 && now - last < def.spawnCooldownTicks) return def.id() + " can spawn again in " + ((def.spawnCooldownTicks - (now - last)) / 20) + " s";
759	        int players = Math.max(1, playersNear(at, def.radius).size());
760	        int number = counter.merge(def.id(), 1, Integer::sum);
761	        double max = def.scaledHealth(players);
762	        Consumer<Mob> init = m -> dressBoss(m, def, number, max, players);
763	        Mob mob = def.spawnBase(at, init);
764	        if (mob == null || !mob.isValid()) return "the spawn was blocked (another plugin or the world's rules)";
765	        clearRiders(mob);
766	        BossBar bar = BossBar.bossBar(Component.text(def.name, def.nameColor), 1f, def.barColor, def.barOverlay);
767	        if (def.darkenSky) bar.addFlag(BossBar.Flag.DARKEN_SCREEN);
768	        BossInstance i = new BossInstance(def, number, mob, at, now, bar, players, encounter);
769	        i.nextAttack = now + def.phases.get(0).interval;
770	        live.add(i);
771	        byEntity.put(mob.getUniqueId(), i);
772	        lastSpawn.put(def.id(), now);
773	        applySelfEffects(i, now);
774	        updateBar(i, participants(i));
775	        if (!def.msgSpawn.isEmpty()) for (Player p : participants(i)) p.sendMessage(Component.text(def.msgSpawn.replace("{boss}", def.name), NamedTextColor.GOLD));
776	        event("boss " + i.key() + " spawned at " + w.getName() + " " + at.getBlockX() + " " + at.getBlockY() + " " + at.getBlockZ() + ": health " + BossDef.fmt(max) + " (" + players + " player" + (players == 1 ? "" : "s") + ")");
777	        return null;
778	    }
