867	    // ---------------------------------------------------------------------------------------------- the AI timer
868	    private void tick() {
869	        long now = d.now();
870	        for (BossInstance i : new ArrayList<>(live)) {
871	            Mob m = i.mob;
872	            if (!m.isValid()) { if (!m.isDead()) despawn(i, "its chunk unloaded"); continue; }
873	            BossDef def = i.def;
874	            if (!inArena(i, m.getLocation())) { m.teleport(i.home); i.leashes++; }
875	            List<Player> ps = participants(i);
876	            updateBar(i, ps);
877	            if (ps.isEmpty()) {
878	                if (i.emptySince < 0) i.emptySince = now;
879	                else if (now - i.emptySince >= def.emptyTicks) { despawn(i, "no players for " + (def.emptyTicks / 20) + " s"); continue; }
880	            } else i.emptySince = -1;
881	            if (!ps.isEmpty()) {
882	                LivingEntity t = m.getTarget();
883	                if (!(t instanceof Player tp) || !ps.contains(tp)) m.setTarget(nearest(ps, m.getLocation()));
884	            }
885	            checkPhase(i);
886	            if (def.maxTicks > 0 && !i.enraged && now - i.started >= def.maxTicks) {
887	                if (def.enrageOnTimeout) {
888	                    i.enraged = true;
889	                    if (!def.msgEnrage.isEmpty()) for (Player p : ps) p.sendMessage(Component.text(def.msgEnrage.replace("{boss}", def.name), NamedTextColor.RED));
890	                    event("boss " + i.key() + " enraged (time out)");
891	                } else { despawn(i, "time out"); continue; }
892	            }
893	            if (now - i.lastEffects >= 40) applySelfEffects(i, now);
894	            if (!ps.isEmpty() && !i.casting && now >= i.nextAttack) choose(i, ps, now);
895	        }
896	        encounters.tick(now);
897	    }
