899	    private static Player nearest(List<Player> ps, Location at) {
900	        Player best = null;
901	        double bd = Double.MAX_VALUE;
902	        for (Player p : ps) { double x = p.getLocation().distanceSquared(at); if (x < bd) { bd = x; best = p; } }
903	        return best;
904	    }
