906	    private void applySelfEffects(BossInstance i, long now) {
907	        i.lastEffects = now;
908	        BossDef.Phase ph = i.def.phases.get(i.phase);
909	        for (int k = 0; k < ph.effects.size(); k++) i.mob.addPotionEffect(new PotionEffect(ph.effects.get(k), 80, ph.amplifiers.get(k), true, false));
910	    }
