912	    /** Enter every phase whose threshold the health fraction is below (one way: healing never goes back). */
913	    void checkPhase(BossInstance i) {
914	        if (!i.mob.isValid()) return;
915	        double f = Checks.healthFraction(i.mob);
916	        while (i.phase + 1 < i.def.phases.size() && f < i.def.phases.get(i.phase + 1).below) {
917	            i.phase++;
918	            BossDef.Phase ph = i.def.phases.get(i.phase);
919	            List<Player> ps = participants(i);
920	            List<LivingEntity> ts = new ArrayList<>(ps);
921	            order(ts, i.mob.getLocation(), BossDef.Select.NEAREST);
922	            if (ts.size() > ENTER_TARGETS) ts = new ArrayList<>(ts.subList(0, ENTER_TARGETS));
923	            BossCast c = BossCast.of(this, i, ts, i.def.damageMultiplier(i.mob.getWorld().getDifficulty(), ps.size(), i.enraged));
924	            i.def.enter(i.phase, c);
925	            applySelfEffects(i, d.now());
926	            i.nextAttack = Math.min(i.nextAttack, d.now() + ph.interval);
927	            updateBar(i, ps);
928	            event("boss " + i.key() + " entered phase " + ph.id + " at " + Math.round(f * 100) + "%");
929	        }
930	    }
