932	    /** Weighted pick (seeded Random.nextInt over the summed weights) among attacks off cooldown that have a target. */
933	    private void choose(BossInstance i, List<Player> ps, long now) {
934	        BossDef.Phase ph = i.def.phases.get(i.phase);
935	        List<BossDef.Attack> ok = new ArrayList<>();
936	        List<Integer> w = new ArrayList<>();
937	        List<List<LivingEntity>> ts = new ArrayList<>();
938	        int total = 0;
939	        for (int k = 0; k < ph.attacks.size(); k++) {
940	            BossDef.Attack a = i.def.attack(ph.attacks.get(k));
941	            if (a == null) continue;
942	            Long r = i.ready.get(a.id);
943	            if (r != null && now < r) continue;
944	            List<LivingEntity> t = targets(i, a, ps);
945	            if (a.select != BossDef.Select.SELF && t.isEmpty()) continue;
946	            ok.add(a); w.add(ph.weights.get(k)); ts.add(t); total += ph.weights.get(k);
947	        }
948	        long interval = i.enraged ? Math.max(10L, ph.interval / 2) : ph.interval;
949	        if (ok.isEmpty() || total <= 0) { i.nextAttack = now + AI_PERIOD; return; }
950	        int roll = random.nextInt(total);
951	        int pick = 0;
952	        for (int k = 0; k < ok.size(); k++) { roll -= w.get(k); if (roll < 0) { pick = k; break; } }
953	        cast(i, ok.get(pick), ts.get(pick), now, true);
954	        i.nextAttack = now + ok.get(pick).telegraph + interval;
955	    }
