957	    /** Telegraph (particle / sound / text at the boss), then the attack's generated actions with a fresh budget. */
958	    int cast(BossInstance i, BossDef.Attack a, List<LivingEntity> targets, long now, boolean telegraph) {
959	        i.ready.put(a.id, now + a.cooldown);
960	        if (telegraph && a.telegraph > 0) {
961	            Location at = i.mob.getLocation().add(0, i.mob.getHeight() + 0.3, 0);
962	            if (a.telegraphParticle != null && at.getWorld() != null) at.getWorld().spawnParticle(a.telegraphParticle, at, 24, 0.6, 0.4, 0.6, 0.02);
963	            if (a.telegraphSound != null && !a.telegraphSound.isEmpty() && at.getWorld() != null) at.getWorld().playSound(at, a.telegraphSound, org.bukkit.SoundCategory.HOSTILE, 1f, 1f);
964	            if (a.telegraphText != null && !a.telegraphText.isEmpty()) for (Player p : participants(i)) p.sendActionBar(Component.text(a.telegraphText.replace("{boss}", i.def.name), NamedTextColor.RED));
965	            i.casting = true;
966	            boolean ok = d.tasks().later(a.telegraph, () -> { i.casting = false; if (alive(i) && i.mob.isValid()) run(i, a, targets); });
967	            if (!ok) i.casting = false;
968	            return targets.size();
969	        }
970	        return run(i, a, targets);
971	    }
