973	    private int run(BossInstance i, BossDef.Attack a, List<LivingEntity> targets) {
974	        int n = participants(i).size();
975	        BossCast c = BossCast.of(this, i, targets, i.def.damageMultiplier(i.mob.getWorld().getDifficulty(), n, i.enraged));
976	        i.def.attack(a.index, c);
977	        return c.targets().size();
978	    }
