1039	    private void defeated(BossInstance i, EntityDeathEvent e) {
1040	        live.remove(i);
1041	        byEntity.remove(i.mob.getUniqueId());
1042	        Location at = i.mob.getLocation();
1043	        List<String> notes = new ArrayList<>();
1044	        List<Player> ps = participants(i);
1045	        String who;
1046	        int stacks = 0;
1047	        DropTable t = i.def.drops;
1048	        if (t.mode() == DropTable.Mode.GROUND) {
1049	            for (ItemStack s : t.roll(random, d, at, notes)) { at.getWorld().dropItemNaturally(at, s); stacks++; }
1050	            e.setDroppedExp(t.xp());
1051	            who = "the ground";
1052	        } else {
1053	            List<Player> got = qualifying(i.damage, ps, t.minShare());
1054	            for (Player p : got) {
1055	                for (ItemStack s : t.roll(random, d, at, notes)) { for (ItemStack left : p.getInventory().addItem(s).values()) p.getWorld().dropItemNaturally(p.getLocation(), left); stacks++; }
1056	                if (t.xp() > 0) p.giveExp(t.xp());
1057	            }
1058	            who = got.isEmpty() ? "nobody (no participant did " + Math.round(t.minShare() * 100) + "% of the damage)" : got.size() + " player" + (got.size() == 1 ? "" : "s");
1059	        }
1060	        hideBar(i);
1061	        if (!i.def.msgDefeat.isEmpty()) for (Player p : ps) p.sendMessage(Component.text(i.def.msgDefeat.replace("{boss}", i.def.name), NamedTextColor.GOLD));
1062	        int n = removeMinions(i);
1063	        for (String s : notes) plugin.getLogger().warning(s);
