1203	import java.util.ArrayList;

// RigSpec v1 (Cyrus R3 creature pipeline): what the build model writes in assets/creatures/<name>.json and what Nxeon's
// compiler (./compile.ts) turns into a Blockbench .bbmodel for the Nxeon-managed BetterModel plugin, a skin PNG and
// baked keyframe animations. The model never writes .bbmodel JSON, UUIDs, UV rectangles or keyframe maths itself.
// Pure + client-safe (Zod + plain TS). The build service's copy (services/modbuilder/creature-spec.js) is GENERATED
// from this file by scripts/cyrus/build-creature-artifacts.ts; test/cyrus-creature.test.ts checks it is current and
// gives the same answer on every fixture. The JSON Schema contract is ./rigspec.v1.schema.json (same script).
//
// Two forms, one schema:
//   template form  { version, name, archetype, template: { features?, height? }, skin: { palette }, sounds, ... }
//                  -> bones + animations come from Nxeon's archetype template (./templates.ts): the reliable path.
//   explicit form  { version, name, archetype, bones: [...], animations: {...}, skin, sounds, ... }
//                  -> for shapes no template covers (still validated against every limit below).
// Coordinates are Blockbench units (16 = one block), absolute (like Blockbench), y up, the creature faces north (-z).
import * as z from "zod/mini";
import { expandTemplate, TEMPLATE_ARCHETYPES, TEMPLATE_FEATURES, TEMPLATE_PALETTE_KEYS } from "./templates";

export const RIG_SPEC_VERSION = 1 as const;
export const ARCHETYPES = ["humanoid", "quadruped", "flyer", "floating_ghost"] as const;
export type Archetype = (typeof ARCHETYPES)[number];
export const REQUIRED_CLIPS = ["idle", "walk", "attack", "hurt", "death"] as const;
export const LOOPING_CLIPS = ["idle", "walk"] as const;
export const FACES = ["north", "east", "south", "west", "up", "down"] as const;
export type Face = (typeof FACES)[number];
export const CHANNELS = ["rotation", "position", "scale"] as const;
export const BONE_TAGS = ["none", "head", "glow"] as const;
/** Vanilla base mobs a creature may ride on (invisible + silent; it provides the hitbox, AI and attributes). */
export const BASE_ENTITIES = ["ZOMBIE", "HUSK", "SKELETON", "STRAY", "VEX", "ALLAY", "WOLF", "PIG", "COW", "SHEEP", "SPIDER", "PHANTOM", "BLAZE", "IRON_GOLEM", "PILLAGER", "WITCH", "CREEPER", "HORSE"] as const;
export const SOUND_ROLES = ["ambient", "hurt", "death", "attack", "step", "spawn"] as const;

// Cost guards (display entities: every bone is one item_display per viewer; every clip is baked into the pack).
export const MAX_BONES = 32;
export const MAX_CUBES = 64;
export const MAX_CUBES_PER_BONE = 12;
export const MAX_DEPTH = 6;
export const MAX_CLIPS = 8;
export const MAX_TRACKS_PER_CLIP = 32;
export const MAX_KEYS_PER_TRACK = 12;
export const MAX_DECALS_PER_FACE = 24;
export const MAX_DECALS_TOTAL = 160;
export const MAX_PALETTE = 16;
export const MAX_COORD = 64;
export const MAX_CREATURES = 4;
export const MAX_RIG_SPEC_BYTES = 48 * 1024;
export const SKIN_SIZES = [64, 128] as const;

export const NAME_RE = /^[a-z][a-z0-9_]{1,31}$/;
export const BONE_RE = /^[a-z][a-z0-9_]{0,23}$/;
export const PALETTE_KEY_RE = /^[a-z][a-z0-9_]{0,15}$/;
export const SOUND_KEY_RE = /^(nx_[a-z0-9]{8}):([a-z][a-z0-9_]{1,31})\.([a-z][a-z0-9_]{0,23})$/;

// zod/mini (not the classic API): the same validator is bundled into the build service, and mini tree-shakes to ~20 KB.
const num = (lo: number, hi: number) => z.number().check(z.minimum(lo), z.maximum(hi));
const int = (lo: number, hi: number) => z.int().check(z.minimum(lo), z.maximum(hi));
const re = (r: RegExp, msg?: string) => z.string().check(z.regex(r, msg));
const def = <T extends z.ZodMiniType>(t: T, v: z.output<T>) => z._default(t, v as never);
const Vec3 = z.tuple([num(-MAX_COORD, MAX_COORD), num(-MAX_COORD, MAX_COORD), num(-MAX_COORD, MAX_COORD)]);
const AngleVec = z.tuple([num(-360, 360), num(-360, 360), num(-360, 360)]);
const Ampl = z.tuple([num(-180, 180), num(-180, 180), num(-180, 180)]);
const paletteKey = re(PALETTE_KEY_RE);
const px = int(0, 127);

const DecalZ = z.discriminatedUnion("op", [
  z.strictObject({ op: z.literal("px"), x: px, y: px, c: paletteKey }),
  z.strictObject({ op: z.literal("rect"), x: px, y: px, w: int(1, 128), h: int(1, 128), c: paletteKey }),
  z.strictObject({ op: z.literal("line"), x1: px, y1: px, x2: px, y2: px, c: paletteKey }),
]);
export type Decal = z.output<typeof DecalZ>;

const CubeZ = z.strictObject({
  from: Vec3,
  to: Vec3,
  /** Palette key of the base colour. Nxeon derives the light/shadow shades itself. */
  material: paletteKey,
  /** solid (default) or fade: a stepped vertical ramp from `material` (top) to `fadeTo` (bottom) on the side faces. */
  shade: def(z.enum(["solid", "fade"]), "solid"),
  fadeTo: z.optional(paletteKey),
  /** Grow the cube by this many units on every side (outer layers like hoods); the texture keeps the base size. */
  inflate: def(num(0, 1), 0),
  /** Small pixel details per face, in face-local pixels (0,0 = top-left of that face as seen from outside). */
  decals: z.optional(z.partialRecord(z.enum(FACES), z.array(DecalZ).check(z.maxLength(MAX_DECALS_PER_FACE)))),
});
export type Cube = z.output<typeof CubeZ>;

const BoneZ = z.strictObject({
  name: re(BONE_RE, "bone names are 1-24 lowercase letters, digits and underscores"),
  parent: z.nullable(re(BONE_RE)),
  pivot: Vec3,
  rotation: z.optional(AngleVec),
  /** head: follows where the mob looks (BetterModel "hi_" tag); glow: always full-bright (eyes, runes). */
  tag: def(z.enum(BONE_TAGS), "none"),
  cubes: def(z.array(CubeZ).check(z.maxLength(MAX_CUBES_PER_BONE)), []),
});
export type Bone = z.output<typeof BoneZ>;

const WaveZ = z.strictObject({
  /** Amplitude per axis (degrees for rotation, units for position, factor for scale). */
  amp: Ampl,
  offset: z.optional(Ampl),
  /** Whole sine cycles over the clip (whole numbers so a loop is seamless). */
  cycles: def(int(1, 8), 1),
  /** Where in the cycle the clip starts, 0-1 (0.5 = opposite phase, e.g. the other leg). */
  phase: def(num(0, 1), 0),
});

const KeyZ = z.strictObject({
  /** Time as a fraction of the clip, 0-1. */
  t: num(0, 1),
  v: AngleVec,
  ease: def(z.enum(["linear", "smooth"]), "smooth"),
});

const TrackZ = z.strictObject({
  bone: re(BONE_RE),
  channel: z.enum(CHANNELS),
  wave: z.optional(WaveZ),
  keys: z.optional(z.array(KeyZ).check(z.minLength(2), z.maxLength(MAX_KEYS_PER_TRACK))),
});
export type Track = z.output<typeof TrackZ>;

const ClipZ = z.strictObject({

const ClipZ = z.strictObject({
  length: num(0.1, 10),
  loop: z.boolean(),
  tracks: z.array(TrackZ).check(z.minLength(1), z.maxLength(MAX_TRACKS_PER_CLIP)),
});
export type Clip = z.output<typeof ClipZ>;

const TemplateZ = z.strictObject({
  /** Optional parts the archetype template knows (see TEMPLATE_FEATURES). */
  features: def(z.array(re(/^[a-z][a-z_]{1,23}$/)).check(z.maxLength(6)), []),
  /** Height multiplier for the template body (1 = default). */
  height: def(num(0.7, 1.5), 1),
});

export const RigSpecV1Schema = z.strictObject({
  version: z.literal(RIG_SPEC_VERSION),
  name: re(NAME_RE, "name is 2-32 lowercase letters, digits and underscores, starting with a letter"),
  displayName: z.optional(z.string().check(z.trim(), z.minLength(2), z.maxLength(40))),
  archetype: z.enum(ARCHETYPES),
  template: z.optional(TemplateZ),
  /** Uniform model scale (1 = Blockbench units as written). */
  scale: def(num(0.4, 3), 1),
  /** The invisible vanilla base mob's box, in blocks (BetterModel draws the model, the base mob is what gets hit). */
  hitbox: z.strictObject({ width: num(0.3, 3), height: num(0.3, 4) }),
  baseEntity: z.enum(BASE_ENTITIES),
  skin: z.strictObject({
    /** 64 or 128 px square sheet; omitted = the smallest that fits the cubes. */
    size: z.optional(z.union([z.literal(64), z.literal(128)])),
    palette: z.record(paletteKey, re(/^#[0-9a-fA-F]{6}$/)),
  }),
  bones: z.optional(z.array(BoneZ).check(z.maxLength(MAX_BONES))),
  animations: z.optional(z.record(re(/^[a-z][a-z0-9_]{1,23}$/), ClipZ)),
  /** Sound-slice keys "<namespace>:<set>.<event>" the plugin plays for this creature (base mob is silenced). */
  sounds: def(z.partialRecord(z.enum(SOUND_ROLES), re(SOUND_KEY_RE, "sound keys are <namespace>:<set>.<event>")), {}),
});

export type RigSpecInput = z.input<typeof RigSpecV1Schema>;
type Parsed = z.output<typeof RigSpecV1Schema>;
/** A validated, EXPANDED RigSpec: bones and every clip are always present (template form resolved). */
export type RigSpec = Omit<Parsed, "bones" | "animations"> & { bones: Bone[]; animations: Record<string, Clip>; skin: { size: 64 | 128 | undefined; palette: Record<string, string> } };

export type RigIssue = { path: string; message: string };
export type RigCheck =
  | { ok: true; spec: RigSpec; warnings: string[]; stats: RigStats }
  | { ok: false; error: string; errors: RigIssue[] };
export type RigStats = { bones: number; cubes: number; clips: number; tracks: number; decals: number; height: number };

/** JSON Schema (draft 2020-12) of what a producer writes (defaults optional). */
export function rigSpecJsonSchema(): Record<string, unknown> {
  return z.toJSONSchema(RigSpecV1Schema, { io: "input" }) as Record<string, unknown>;
}

const dims = (c: { from: number[]; to: number[] }) => [0, 1, 2].map((i) => c.to[i] - c.from[i]);
/** Texture footprint of a cube face in pixels (the compiler uses exactly this; decals are checked against it). */
export function faceSize(c: { from: number[]; to: number[] }, face: Face): [number, number] {
  const [w, h, d] = dims(c).map((v) => Math.max(1, Math.ceil(v - 1e-9)));
  if (face === "north" || face === "south") return [w, h];
  if (face === "east" || face === "west") return [d, h];
  return [w, d];
}

function decalBox(d: Decal): [number, number, number, number] {
  if (d.op === "px") return [d.x, d.y, d.x, d.y];
  if (d.op === "rect") return [d.x, d.y, d.x + d.w - 1, d.y + d.h - 1];
  return [Math.min(d.x1, d.x2), Math.min(d.y1, d.y2), Math.max(d.x1, d.x2), Math.max(d.y1, d.y2)];
}

/**
 * Validate untrusted JSON into an expanded RigSpec. Never throws. `namespace`, when given, must own every sound key.
 * Errors come back as a list plus `error` = the first one (what the build model is shown).
 */
export function checkRigSpec(raw: unknown, ctx: { namespace?: string } = {}): RigCheck {
  const fail = (errors: RigIssue[]): RigCheck => ({ ok: false, error: errors.map((e) => (e.path ? `${e.path}: ${e.message}` : e.message))[0] ?? "invalid", errors: errors.slice(0, 20) });
  const p = RigSpecV1Schema.safeParse(raw);
  if (!p.success) return fail(p.error.issues.map((i) => ({ path: i.path.map(String).join("."), message: i.message })));
  const s = p.data;
  const errors: RigIssue[] = [];
  const warnings: string[] = [];
  const err = (path: string, message: string) => errors.push({ path, message });

  // palette
  const pal = Object.keys(s.skin.palette);
  if (pal.length < 2 || pal.length > MAX_PALETTE) err("skin.palette", `needs 2-${MAX_PALETTE} colours`);

  // template form vs explicit form
  let bones: Bone[];
  let animations: Record<string, Clip>;
  if (s.template) {
    if (s.bones || s.animations) return fail([{ path: "template", message: "use either template or bones + animations, not both" }]);
    if (!(TEMPLATE_ARCHETYPES as readonly string[]).includes(s.archetype)) return fail([{ path: "archetype", message: `no template for ${s.archetype}; templates exist for ${TEMPLATE_ARCHETYPES.join(", ")} (write bones + animations instead)` }]);
    const known = TEMPLATE_FEATURES[s.archetype as (typeof TEMPLATE_ARCHETYPES)[number]];
    for (const f of s.template.features) if (!known.includes(f)) err("template.features", `unknown feature ${f} for ${s.archetype} (known: ${known.join(", ")})`);
    for (const k of TEMPLATE_PALETTE_KEYS[s.archetype as (typeof TEMPLATE_ARCHETYPES)[number]]) if (!(k in s.skin.palette)) err("skin.palette", `the ${s.archetype} template needs the colour "${k}" (needs: ${TEMPLATE_PALETTE_KEYS[s.archetype as (typeof TEMPLATE_ARCHETYPES)[number]].join(", ")})`);
    if (errors.length) return fail(errors);
    const t = expandTemplate(s.archetype as (typeof TEMPLATE_ARCHETYPES)[number], s.template);
    bones = t.bones.map((b) => BoneZ.parse(b));
    animations = Object.fromEntries(Object.entries(t.animations).map(([k, v]) => [k, ClipZ.parse(v)]));
  } else {
    if (!s.bones || !s.animations) return fail([{ path: "", message: "give template (recommended) or both bones and animations" }]);
    bones = s.bones;
    animations = s.animations;
  }

  // bones: unique, one root, parents exist, acyclic, depth
  const byName = new Map<string, Bone>();
  for (const [i, b] of bones.entries()) {
    if (byName.has(b.name)) err(`bones.${i}.name`, `duplicate bone ${b.name}`);
    byName.set(b.name, b);
  }
  if (!bones.length) err("bones", "needs at least one bone");
  const roots = bones.filter((b) => b.parent === null);
  if (roots.length !== 1) err("bones", `needs exactly one root bone (parent null), found ${roots.length}`);
  for (const [i, b] of bones.entries()) {
    if (b.parent !== null && !byName.has(b.parent)) err(`bones.${i}.parent`, `unknown parent ${b.parent}`);
    let depth = 0, cur: Bone | undefined = b;
    const seen = new Set<string>();
    while (cur && cur.parent !== null) {
      if (seen.has(cur.name)) { err(`bones.${i}`, `bone ${b.name} is part of a parent cycle`); break; }
      seen.add(cur.name);
      cur = byName.get(cur.parent);
      depth++;
    }
    if (depth > MAX_DEPTH) err(`bones.${i}`, `bone ${b.name} is nested ${depth} deep; the limit is ${MAX_DEPTH}`);
  }

  // cubes + decals
  let cubes = 0, decals = 0, minY = Infinity, maxY = -Infinity;
  const usedTags = { head: 0, glow: 0 };
  for (const [i, b] of bones.entries()) {
    if (b.tag === "head") usedTags.head++;
    for (const [j, c] of b.cubes.entries()) {
      cubes++;
      const at = `bones.${i}.cubes.${j}`;
      const d = dims(c);
      if (d.some((v) => v < 0.2)) err(at, "every cube side must be at least 0.2 units (to > from)");
      if (d.some((v) => v > 48)) err(at, "a cube side may be at most 48 units");
      if (!(c.material in s.skin.palette)) err(`${at}.material`, `unknown palette colour ${c.material}`);
      if (c.shade === "fade" && !(c.fadeTo && c.fadeTo in s.skin.palette)) err(`${at}.fadeTo`, "shade fade needs fadeTo, a palette colour");
      if (c.fadeTo && !(c.fadeTo in s.skin.palette)) err(`${at}.fadeTo`, `unknown palette colour ${c.fadeTo}`);
      minY = Math.min(minY, c.from[1] - c.inflate); maxY = Math.max(maxY, c.to[1] + c.inflate);
      for (const face of FACES) {
        const list = c.decals?.[face] ?? [];
        decals += list.length;
        const [fw, fh] = faceSize(c, face);
        for (const [k, dc] of list.entries()) {
          if (!(dc.c in s.skin.palette)) err(`${at}.decals.${face}.${k}`, `unknown palette colour ${dc.c}`);
          const [x0, y0, x1, y1] = decalBox(dc);
          if (x0 < 0 || y0 < 0 || x1 >= fw || y1 >= fh) err(`${at}.decals.${face}.${k}`, `outside the ${face} face (${fw}x${fh} px)`);
        }
      }
    }
  }
  if (usedTags.head > 1) err("bones", "only one bone may have tag head");
  if (cubes > MAX_CUBES) err("bones", `${cubes} cubes; the limit is ${MAX_CUBES}`);
  if (!cubes) err("bones", "the creature has no cubes");
  if (decals > MAX_DECALS_TOTAL) err("bones", `${decals} decals; the limit is ${MAX_DECALS_TOTAL}`);

  // animations
  const clipNames = Object.keys(animations);
  for (const c of REQUIRED_CLIPS) if (!(c in animations)) err("animations", `missing the ${c} clip (required: ${REQUIRED_CLIPS.join(", ")})`);
  if (clipNames.length > MAX_CLIPS) err("animations", `${clipNames.length} clips; the limit is ${MAX_CLIPS}`);
  let tracks = 0;
  for (const [name, clip] of Object.entries(animations)) {
    const at = `animations.${name}`;
    if ((LOOPING_CLIPS as readonly string[]).includes(name) && !clip.loop) err(`${at}.loop`, `${name} must loop`);
    if (name === "death" || name === "attack" || name === "hurt") { if (clip.loop) err(`${at}.loop`, `${name} plays once (loop false)`); }
    const seen = new Set<string>();
    for (const [i, t] of clip.tracks.entries()) {
      tracks++;
      const ta = `${at}.tracks.${i}`;
      if (!byName.has(t.bone)) err(`${ta}.bone`, `unknown bone ${t.bone}`);
      const key = `${t.bone}/${t.channel}`;
      if (seen.has(key)) err(ta, `two tracks animate ${key}`);
      seen.add(key);
      if (!!t.wave === !!t.keys) { err(ta, "a track needs exactly one of wave or keys"); continue; }
      const lim = t.channel === "rotation" ? 360 : t.channel === "position" ? 32 : 4;
      if (t.wave) {
        const mx = [0, 1, 2].map((k) => Math.abs((t.wave!.offset?.[k] ?? 0)) + Math.abs(t.wave!.amp[k]));
        if (mx.some((v) => v > lim)) err(`${ta}.wave`, `${t.channel} values must stay within ${lim}`);
        if (t.channel === "scale" && [0, 1, 2].some((k) => 1 + (t.wave!.offset?.[k] ?? 0) - Math.abs(t.wave!.amp[k]) < 0)) err(`${ta}.wave`, "scale may not go below 0");
      } else {
        const ks = t.keys!;
        if (ks[0].t !== 0 || ks[ks.length - 1].t !== 1) err(`${ta}.keys`, "keys must start at t 0 and end at t 1");
        for (let k = 1; k < ks.length; k++) if (!(ks[k].t > ks[k - 1].t)) err(`${ta}.keys.${k}.t`, "key times must increase");
        for (const [k, kv] of ks.entries()) {
          if (kv.v.some((v) => Math.abs(v) > lim)) err(`${ta}.keys.${k}.v`, `${t.channel} values must stay within ${lim}`);
          if (t.channel === "scale" && kv.v.some((v) => v < 0)) err(`${ta}.keys.${k}.v`, "scale may not be negative");
        }
        if (clip.loop && ks.length >= 2 && ks[0].v.some((v, k) => Math.abs(v - ks[ks.length - 1].v[k]) > 1e-6)) err(`${ta}.keys`, "a looping clip must end where it starts (first and last key equal)");
      }
    }
  }

  // sounds
  for (const [role, key] of Object.entries(s.sounds)) {
    const m = SOUND_KEY_RE.exec(key!);
    if (m && ctx.namespace && m[1] !== ctx.namespace) err(`sounds.${role}`, `uses the namespace ${m[1]}; this mod's reserved namespace is ${ctx.namespace}`);
  }

  if (errors.length) return fail(errors);

  // soft facts (never block)
  const height = Math.round((maxY - Math.min(0, minY)) * s.scale * 100) / 100;
  const modelBlocks = height / 16;
  if (s.hitbox.height > modelBlocks * 1.6 + 0.2 || s.hitbox.height < modelBlocks * 0.4) warnings.push(`hitbox height ${s.hitbox.height} blocks does not match the model (about ${modelBlocks.toFixed(2)} blocks tall)`);
  if (!usedTags.head) warnings.push("no bone has tag head, so the model will not look where the mob looks");
  for (const r of ["hurt", "death", "attack"] as const) if (!s.sounds[r]) warnings.push(`no ${r} sound: the creature is silent when it ${r === "attack" ? "attacks" : r === "hurt" ? "is hurt" : "dies"} (the base mob is silenced)`);

  const spec: RigSpec = { ...s, bones, animations, skin: { size: s.skin.size, palette: Object.fromEntries(Object.entries(s.skin.palette).map(([k, v]) => [k, v.toLowerCase()])) } };
  // The expanded spec is fully explicit (and validates to itself): the template choice is not kept in it.
  delete (spec as { template?: unknown }).template;
  return { ok: true, spec, warnings, stats: { bones: bones.length, cubes, clips: clipNames.length, tracks, decals, height } };
}

/** The BetterModel model key for a creature: `<namespace>_<name>` (file plugins/BetterModel/models/<key>.bbmodel). */
export const modelKey = (namespace: string, name: string) => `${namespace}_${name}`;

package dev.nxeon.tf.creature;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import kr.toxicity.model.api.BetterModel;
import kr.toxicity.model.api.animation.AnimationModifier;
import kr.toxicity.model.api.bukkit.platform.BukkitAdapter;
import kr.toxicity.model.api.data.renderer.ModelRenderer;
import kr.toxicity.model.api.tracker.EntityTracker;
import org.bukkit.Bukkit;
import org.bukkit.Difficulty;
import org.bukkit.Location;
import org.bukkit.SoundCategory;
import org.bukkit.World;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.EntityType;
import org.bukkit.entity.LivingEntity;
import org.bukkit.entity.Zombie;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * Cyrus R3 creature-pipeline Test Flight fixture. Does what the CREATURE section tells a generated mod to do: spawn a
 * vanilla base mob, make it silent + invisible, attach the compiled model with BetterModel's API
 * (BetterModel.model("<namespace>_<name>") -> renderer.create(BukkitAdapter.adapt(entity))), loop "idle", play
 * "attack" once and its namespaced sound key, and close the tracker before removing the mob. Server side only: no client
 * is connected, so nothing here proves how the creature LOOKS or animates for a player.
 */
public class CreaturePlugin extends JavaPlugin {
    private final List<LivingEntity> mobs = new ArrayList<>();
    private final List<EntityTracker> trackers = new ArrayList<>();
    private final AtomicInteger finished = new AtomicInteger();

    @Override
    public void onDisable() {
        for (EntityTracker t : trackers) if (!t.isClosed()) t.close();
        for (LivingEntity e : mobs) if (e.isValid()) e.remove();
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        String step = "args";
        try {
            if (args.length == 0) { sender.sendMessage("usage: /tfcreature <models|spawn|attack|hurt|death|stats|despawn>"); return true; }
            World world = getServer().getWorlds().get(0);
            switch (args[0]) {
                case "models": {
                    step = "modelKeys";
                    String want = args.length > 1 ? args[1] : "";
                    sender.sendMessage("models=" + BetterModel.modelKeys().size() + " has=" + (want.isEmpty() ? "-" : String.valueOf(BetterModel.modelOrNull(want) != null)) + " keys=" + String.join(",", new java.util.TreeSet<>(BetterModel.modelKeys())));
                    return true;
                }
                case "spawn": {
                    String key = args[1];
                    int n = Integer.parseInt(args[2]);
                    step = "model";
                    ModelRenderer r = BetterModel.modelOrNull(key);
                    if (r == null) { sender.sendMessage("error: no model " + key); return true; }
                    if (world.getDifficulty() == Difficulty.PEACEFUL) world.setDifficulty(Difficulty.EASY);
                    Location base = world.getSpawnLocation();
                    // 26.x has no always-loaded spawn chunks and a flight has no player: force-load the area so the base
                    // mobs stay loaded and ticking (a generated mod spawns near players, where chunks are loaded anyway)
                    step = "chunks";
                    for (int cx = (base.getBlockX() >> 4) - 1; cx <= ((base.getBlockX() + 30) >> 4) + 1; cx++)
                        for (int cz = (base.getBlockZ() >> 4) - 1; cz <= ((base.getBlockZ() + 15) >> 4) + 1; cz++) world.setChunkForceLoaded(cx, cz, true);
                    int made = 0, idle = 0;
                    for (int i = 0; i < n; i++) {
                        step = "spawn";
                        Location at = base.clone().add((i % 10) * 2.5, 0, (i / 10) * 2.5);
                        LivingEntity mob = (LivingEntity) world.spawnEntity(at, EntityType.ZOMBIE);
                        mob.setSilent(true);
                        mob.setInvisible(true);
                        mob.setPersistent(true);
                        if (mob instanceof Zombie z) { z.setShouldBurnInDay(false); z.setAdult(); }
                        step = "tracker";
                        EntityTracker t = r.create(BukkitAdapter.adapt(mob));
                        mobs.add(mob); trackers.add(t); made++;
                        step = "idle";
                        if (t.animate("idle")) idle++;
                    }
                    sender.sendMessage("spawned=" + made + " idle=" + idle + " trackers=" + trackers.size() + " silent=" + mobs.get(0).isSilent() + " invisible=" + mobs.get(0).isInvisible() + " zombies=" + world.getEntitiesByClass(Zombie.class).size() + " difficulty=" + world.getDifficulty().name());
                    return true;
                }
                case "attack": case "hurt": case "death": {
                    String clip = args[0];
                    String sound = args.length > 1 ? args[1] : null;
                    int ok = 0;
                    for (int i = 0; i < trackers.size(); i++) {
                        EntityTracker t = trackers.get(i);
                        LivingEntity mob = mobs.get(i);
                        step = clip;
                        boolean started;
                        if (clip.equals("death")) {
                            started = t.animate("death", AnimationModifier.DEFAULT_WITH_PLAY_ONCE, () -> {
                                finished.incrementAndGet();
                                // the plugin removes the mob after its death clip (BetterModel "hold" keeps the last pose until then)
                                Bukkit.getScheduler().runTask(this, () -> { t.close(); mob.remove(); });
                            });
                        } else {
                            started = t.animate(clip, AnimationModifier.DEFAULT_WITH_PLAY_ONCE, finished::incrementAndGet);
                            if (clip.equals("hurt")) t.damageTint();
                        }
                        if (started) ok++;
                        step = "sound";
                        if (sound != null) world.playSound(mob.getLocation(), sound, SoundCategory.HOSTILE, 1.0f, 1.0f);
                    }
                    sender.sendMessage(clip + "_started=" + ok + " of=" + trackers.size() + (sound != null ? " sound=" + sound : ""));
                    return true;
                }
                case "stats": {
                    step = "stats";
                    Runtime rt = Runtime.getRuntime();
                    long open = trackers.stream().filter(t -> !t.isClosed()).count();
                    long scheduled = trackers.stream().filter(t -> !t.isClosed() && t.isScheduled()).count();
                    int viewers = trackers.stream().filter(t -> !t.isClosed()).mapToInt(t -> t.playerCount()).sum();
                    long alive = mobs.stream().filter(LivingEntity::isValid).count();
                    sender.sendMessage(String.format(java.util.Locale.ROOT, "mspt=%.2f tps=%.2f zombies=%d entities=%d trackersOpen=%d scheduled=%d viewers=%d mobsAlive=%d finished=%d heapUsedMb=%d",
                        Bukkit.getAverageTickTime(), Bukkit.getTPS()[0], world.getEntitiesByClass(Zombie.class).size(), world.getEntities().size(), open, scheduled, viewers, alive, finished.get(), (rt.totalMemory() - rt.freeMemory()) / (1024 * 1024)));
                    return true;
                }
                case "despawn": {
                    step = "despawn";
                    int closed = 0;
                    for (EntityTracker t : trackers) if (!t.isClosed()) { t.close(); closed++; }
                    int removed = 0;
                    for (LivingEntity e : mobs) if (e.isValid()) { e.remove(); removed++; }
                    trackers.clear(); mobs.clear(); finished.set(0);
                    sender.sendMessage("closed=" + closed + " removed=" + removed + " zombies=" + world.getEntitiesByClass(Zombie.class).size());
                    return true;
                }
                default: sender.sendMessage("unknown subcommand"); return true;
            }
        } catch (Throwable t) {
            sender.sendMessage("error at " + step + ": " + t.getClass().getName() + ": " + t.getMessage());
            return true;
        }
    }
}
