// ---- rc12: plugin.yml depend / softdepend autofix -------------------------------------------------------------------------
// Live bug (owner's goblin mod): the sources imported kr.toxicity.model.* but plugin.yml had no `depend: [BetterModel]`, so the plugin
// failed to enable in Test Flight ("Goblins: NOT enabled") while the build "succeeded". Deterministic, text-level, keeps every other
// key and comment. A plugin the sources import the API of must be declared: BetterModel is a hard `depend` (the creature code cannot
// run without it, and a softdepend entry is moved), the other managed plugins (PlaceholderAPI, Vault, LuckPerms, ProtocolLib; ids
// and packages come from lib/cyrus/import/deps.json) are `softdepend` unless already in either list.
const DEPEND_PKG_PLUGINS = [
  { plugin: "BetterModel", packages: ["kr.toxicity.model.api"], hard: true },
  { plugin: "PlaceholderAPI", packages: ["me.clip.placeholderapi"], hard: false },
  { plugin: "Vault", packages: ["net.milkbowl.vault"], hard: false },
  { plugin: "LuckPerms", packages: ["net.luckperms.api"], hard: false },
  { plugin: "ProtocolLib", packages: ["com.comphenix.protocol"], hard: false },
];

/** Plugins whose API the Java text imports (import statements and fully-qualified uses), in table order. */
function importedPlugins(javaText) {
  const t = String(javaText || "");
  return DEPEND_PKG_PLUGINS.filter((d) => d.packages.some((p) => new RegExp(`(^|[^\\w.])${p.replace(/\./g, "\\.")}\\.`, "m").test(t)));
}

function stripScalar(s) { return String(s).trim().replace(/^["']|["']$/g, "").trim(); }

/** Locate a top-level list key in plugin.yml text. Returns { start, end (exclusive line idx), items, block, itemIndent } or null. */
function findListKey(lines, key) {
  const re = new RegExp(`^${key}[ \\t]*:(.*)$`);
  for (let i = 0; i < lines.length; i++) {
    const m = re.exec(lines[i]);
    if (!m) continue;
    const rest = m[1].replace(/\s+#.*$/, "").trim();
    let end = i + 1;
    const items = [];
    let block = false;
    let itemIndent = "  ";
    if (rest.startsWith("[")) {
      const inner = rest.replace(/^\[/, "").replace(/\].*$/, "");
      for (const x of inner.split(",")) if (stripScalar(x)) items.push(stripScalar(x));
    } else if (rest && !/^[|>]/.test(rest)) {
      for (const x of rest.split(",")) if (stripScalar(x)) items.push(stripScalar(x));
    } else {
      block = true;
      while (end < lines.length) {
        const l = lines[end];
        const im = /^(\s*)-\s+(.*?)\s*(?:#.*)?$/.exec(l);
        if (im) { items.push(stripScalar(im[2])); itemIndent = im[1]; end++; continue; }
        if (!l.trim() || /^\s*#/.test(l)) {
          // trailing blank/comment lines belong to the next key unless another item follows
          let j = end; while (j < lines.length && (!lines[j].trim() || /^\s*#/.test(lines[j]))) j++;
          if (j < lines.length && /^\s*-\s+/.test(lines[j])) { end = j; continue; }
        }
        break;
      }
    }
    return { start: i, end, items, block, itemIndent };
  }
  return null;
}

/** Declared plugin names in depend / softdepend (text level, no YAML library). */
function declaredPlugins(ymlText) {
  const lines = String(ymlText).split("\n");
  const d = findListKey(lines, "depend");
  const s = findListKey(lines, "softdepend");
  return { depend: d ? d.items : [], softdepend: s ? s.items : [] };
}

function renderList(key, items, found) {
  if (found && found.block) return [`${key}:`, ...items.map((x) => `${found.itemIndent}- ${x}`)];
  return [`${key}: [${items.join(", ")}]`];
}

/**
 * Returns { text, changes:[{kind:"depend-add"|"softdepend-add"|"depend-move", plugin, ...}] } or null (nothing to do, or the result
 * does not parse / does not declare what it should: the soft check stays as backstop). `parse` = YAML.parse.
 * `force`: plugin names that must be present even without an import (e.g. ["BetterModel"] when the build has creatures).
 */
function fixPluginDepends(ymlText, javaText, parse, force = []) {
  const wanted = importedPlugins(javaText);
  for (const f of force) { const d = DEPEND_PKG_PLUGINS.find((x) => x.plugin === f); if (d && !wanted.includes(d)) wanted.push(d); }
  if (!wanted.length) return null;
  let lines = String(ymlText).split("\n");
  const changes = [];
  const setKey = (key, items, found, insertAt) => {
    if (found) {
      lines.splice(found.start, found.end - found.start, ...(items.length ? renderList(key, items, found) : []));
    } else if (items.length) lines.splice(insertAt(), 0, ...renderList(key, items, null));
  };
  const insertAfterMain = () => {
    let i = lines.findIndex((l) => /^main\s*:/.test(l));
    if (i < 0) { i = lines.findIndex((l) => /^name\s*:/.test(l)); }
    if (i < 0) { let n = lines.length; while (n > 0 && !lines[n - 1].trim()) n--; return n; }
    return i + 1;
  };
  for (const w of wanted) {
    const dep = findListKey(lines, "depend");
    const soft = findListKey(lines, "softdepend");
    const inDep = dep && dep.items.some((x) => x.toLowerCase() === w.plugin.toLowerCase());
    const inSoft = soft && soft.items.some((x) => x.toLowerCase() === w.plugin.toLowerCase());
    if (inDep) continue;
    if (w.hard) {
      if (inSoft) {
        // moved: a soft entry would let the plugin load without the engine it cannot run without
        const rest = soft.items.filter((x) => x.toLowerCase() !== w.plugin.toLowerCase());
        setKey("softdepend", rest, soft, insertAfterMain);
        changes.push({ kind: "depend-move", plugin: w.plugin });
      } else changes.push({ kind: "depend-add", plugin: w.plugin });
      const dep2 = findListKey(lines, "depend");
      setKey("depend", [...(dep2 ? dep2.items : []), w.plugin], dep2, insertAfterMain);
    } else if (!inSoft) {
      setKey("softdepend", [...(soft ? soft.items : []), w.plugin], soft, insertAfterMain);
      changes.push({ kind: "softdepend-add", plugin: w.plugin });
    }
  }
  if (!changes.length) return null;
  const text = lines.join("\n");
  try {
    const y = parse(text);
    const dd = [].concat(y.depend || []).map(String).map((x) => x.toLowerCase());
    const ss = [].concat(y.softdepend || []).map(String).map((x) => x.toLowerCase());
    for (const w of wanted) {
      if (w.hard ? !dd.includes(w.plugin.toLowerCase()) : !dd.includes(w.plugin.toLowerCase()) && !ss.includes(w.plugin.toLowerCase())) return null;
    }
    if (typeof y.name !== "string" && typeof y.name !== "number") return null;
  } catch { return null; }
  return { text, changes };
}

/** Plain-English note for the model when a repair still follows an auto-fix round. */
function fixNote(fixes) {
  if (!fixes || !fixes.length) return "";
  return `The build service already corrected these lines automatically (keep them; Read a file again before editing it if it is listed):\n${fixes.slice(0, 20).map((f) => `- ${f.file}:${f.line}: ${f.from ? `${f.from} -> ` : ""}${f.to}`).join("\n")}\n\n`;
}

/**
 * rc13: the commands a build LISTS (summary.json usage, what the owner and the Test Flight use) must be commands plugin.yml
 * registers. A root label that is neither a declared command nor an alias is rewritten to the one it must mean: the only
 * declared command, or the single declared command whose name contains / is contained in the label (fireswordmod ->
 * firesword). Several candidates or none = left alone and reported in `unresolved` (never guessed). Pure.
 * commands = [{usage,...}], ymlCommands = plugin.yml `commands:` map, howToUse = string[] (the same rename is applied
 * to "/old" mentions there). Returns { commands, howToUse, changes: [{from,to}], unresolved: [label] }.
 */
      const recordFixes = (compiledOk) => {
        if (fixesRecorded || !roundFixes.length) return;
        fixesRecorded = true;
        rec.autofixes = [...(rec.autofixes || []), ...roundFixes.map((f) => ({ ...f, attempt: rec.attempts }))].slice(-40);
        rec.usage.autofix = (rec.usage.autofix || 0) + roundFixes.length;
        if (compiledOk) rec.usage.savedRepairs = (rec.usage.savedRepairs || 0) + 1;
