      let problem = null;
      // Known-bad API patterns for this version (reviewed rules). A hit that is
      // still there after the model was told once is left to javac, so a false
      // positive can cost at most one repair.
      if (AUTOFIX && !v.problems.length && !designProblem) {
        t0 = Date.now();
        try {
          const srcs = listFiles(ws, "src/main/java").filter((f) => f.rel.endsWith(".java"));
          const fx = [...AF.fixImports(srcs, rec.mcVersion, { classIndex }).fixes, ...AF.fixGameRules(srcs, rec.mcVersion, { classIndex, members }).fixes];
          if (fx.length) { roundFixes.push(...fx); event(rec, rec.status, `Fixed ${fx.length} import${fx.length > 1 ? "s" : ""} automatically`); }
          // rc12 (goblin mod): plugin.yml must declare the plugins whose API the sources import (BetterModel = depend, others = softdepend).
          if (!rec.imported) {
